choose.when:
AND (
    ${ownerColumn} = #{orderView.userId}
    OR EXISTS (
        SELECT 1 FROM sys_user_dept owner_dept
        INNER JOIN recursion_mapping owner_tree
            ON owner_tree.node_id = owner_dept.dept_id AND owner_tree.node_type = 1
        INNER JOIN sys_user_dept viewer_dept
            ON FIND_IN_SET(viewer_dept.dept_id, owner_tree.path) > 0
                AND viewer_dept.dept_id != owner_dept.dept_id
        WHERE owner_dept.user_id = ${ownerColumn}
            AND viewer_dept.user_id = #{orderView.userId}
    )
)

AND EXISTS (
    SELECT 1 FROM sys_user_dept owner_dept
    INNER JOIN sys_user_dept viewer_dept ON viewer_dept.dept_id = owner_dept.dept_id
    WHERE owner_dept.user_id = ${ownerColumn}
        AND viewer_dept.user_id = #{orderView.userId}
)
